test("denial date counts as day 0", function () {
  assert.deepEqual(
    code.checkAppealWindow({ denialDate: "2026-01-10", checkDate: "2026-01-10" }),
    { allowed: true, daysLeft: 120, elapsedDays: 0 }
  );
});

test("days left equals 120 minus elapsed days", function () {
  assert.deepEqual(
    code.checkAppealWindow({ denialDate: "2026-01-10", checkDate: "2026-03-10" }),
    { allowed: true, daysLeft: 61, elapsedDays: 59 }
  );
});

test("elapsed 120 is still allowed with 0 days left", function () {
  assert.deepEqual(
    code.checkAppealWindow({ denialDate: "2026-01-10", checkDate: "2026-05-10" }),
    { allowed: true, daysLeft: 0, elapsedDays: 120 }
  );
});

test("elapsed 121 is closed and days left is 0 not negative", function () {
  assert.deepEqual(
    code.checkAppealWindow({ denialDate: "2026-01-10", checkDate: "2026-05-11" }),
    { allowed: false, daysLeft: 0, elapsedDays: 121 }
  );
});

test("elapsed 1 is one step above day 0", function () {
  assert.deepEqual(
    code.checkAppealWindow({ denialDate: "2026-01-10", checkDate: "2026-01-11" }),
    { allowed: true, daysLeft: 119, elapsedDays: 1 }
  );
});

test("elapsed 119 is one step below day 120", function () {
  assert.deepEqual(
    code.checkAppealWindow({ denialDate: "2026-01-10", checkDate: "2026-05-09" }),
    { allowed: true, daysLeft: 1, elapsedDays: 119 }
  );
});

test("first and last day of January does not count the end date twice", function () {
  assert.deepEqual(
    code.checkAppealWindow({ denialDate: "2026-01-01", checkDate: "2026-01-31" }),
    { allowed: true, daysLeft: 90, elapsedDays: 30 }
  );
});

test("last day of a month to the first of the next is one day", function () {
  assert.deepEqual(
    code.checkAppealWindow({ denialDate: "2026-01-31", checkDate: "2026-02-01" }),
    { allowed: true, daysLeft: 119, elapsedDays: 1 }
  );
});

test("December 1st to January 31st across the year", function () {
  assert.deepEqual(
    code.checkAppealWindow({ denialDate: "2025-12-01", checkDate: "2026-01-31" }),
    { allowed: true, daysLeft: 59, elapsedDays: 61 }
  );
});

test("December 31st to January 1st is one day", function () {
  assert.deepEqual(
    code.checkAppealWindow({ denialDate: "2025-12-31", checkDate: "2026-01-01" }),
    { allowed: true, daysLeft: 119, elapsedDays: 1 }
  );
});

test("leap day is a real calendar date", function () {
  assert.deepEqual(
    code.checkAppealWindow({ denialDate: "2024-02-29", checkDate: "2024-03-01" }),
    { allowed: true, daysLeft: 119, elapsedDays: 1 }
  );
});

test("leap February 1st to March 1st counts 29 days", function () {
  assert.deepEqual(
    code.checkAppealWindow({ denialDate: "2024-02-01", checkDate: "2024-03-01" }),
    { allowed: true, daysLeft: 91, elapsedDays: 29 }
  );
});

test("leap day inside the window flips day 120 to closed", function () {
  assert.deepEqual(
    code.checkAppealWindow({ denialDate: "2024-01-10", checkDate: "2024-05-10" }),
    { allowed: false, daysLeft: 0, elapsedDays: 121 }
  );
});

test("invalid date throws invalid date for checkDate", function () {
  assert.throws(function () {
    code.checkAppealWindow({ denialDate: "2026-01-10", checkDate: "2026-02-29" });
  }, /^invalid date: checkDate$/);
});

test("missing field throws missing field for checkDate", function () {
  assert.throws(function () {
    code.checkAppealWindow({ denialDate: "2026-01-10" });
  }, /^missing field: checkDate$/);
});

test("unknown field throws unknown field for patientId", function () {
  assert.throws(function () {
    code.checkAppealWindow({ denialDate: "2026-01-10", checkDate: "2026-01-10", patientId: "x" });
  }, /^unknown field: patientId$/);
});
